class FfiCallCtx:
    """
    What a host says about one call: the trace fields it continues and, for a
    list, the reads it chooses.

    The record belongs to the call, never to the client: two calls of one
    client carry their own trace fields. Every async export, list, batch and
    stream accepts one; `FfiCallCtx::default()` is a call that starts a new trace
    and leaves the reads to the Layer 2 method.
"""
    def __init__(self, *, traceparent:typing.Optional[str] = _DEFAULT, tracestate:typing.Optional[str] = _DEFAULT, prefetch:typing.Optional[int] = _DEFAULT, first_only:bool = False):
        if traceparent is _DEFAULT:
            self.traceparent = None
        else:
            self.traceparent = traceparent
        if tracestate is _DEFAULT:
            self.tracestate = None
        else:
            self.tracestate = tracestate
        if prefetch is _DEFAULT:
            self.prefetch = None
        else:
            self.prefetch = prefetch
        self.first_only = first_only
        
        

    
    def __str__(self):
        return "FfiCallCtx(traceparent={}, tracestate={}, prefetch={}, first_only={})".format(self.traceparent, self.tracestate, self.prefetch, self.first_only)
    def __eq__(self, other):
        if self.traceparent != other.traceparent:
            return False
        if self.tracestate != other.tracestate:
            return False
        if self.prefetch != other.prefetch:
            return False
        if self.first_only != other.first_only:
            return False
        return True

